package org.agentfrc.lesson;
import edu.wpi.first.math.system.plant.DCMotor;import edu.wpi.first.wpilibj.simulation.*;
/** Shared longitudinal chassis/piece dynamics with four actual controller output branches. */
public final class MovingSeasonRig implements AutoCloseable {
 public record Params(double mass,double driveJ,double radius,double gear,double mu,double initialVelocity,double target){public Params{if(!Double.isFinite(mass)||mass<10||mass>100||!Double.isFinite(driveJ)||driveJ<.001||driveJ>1||radius!=.0762||!Double.isFinite(gear)||gear<1||gear>30||!Double.isFinite(mu)||mu<0||mu>2||!Double.isFinite(initialVelocity)||initialVelocity<0||initialVelocity>1||!Double.isFinite(target)||target<0||target>1)throw new IllegalArgumentException("Moving hypothesis domain");}}
 public record Sample(double bodyX,double pieceX,double relativeX,double bodyV,double pieceV,double bus,double batteryA,double driveA,double mechanismA,double reactionImpulse,double mechanicalResidual,double momentum,boolean engaged,boolean released,boolean beam,boolean done,boolean faulted,double[] shafts){}
 private final SeasonRollerRig.Config c;private final Params p;private final MovingContact contact;private final MovingPrototypeController controller;private final EncoderSim[] sensors;private final PWMSim[] motors;private final DIOSim beam;private final PWMSim unusedAux;private final DCMotor dm,mm;private double[] q;private final double[] angles=new double[4];private double elapsed,bx,px,bus=12,totalWork,loss,initialEnergy,amps,driveA,mechanismA,reaction;private boolean released,engaged;private final boolean worldBeamFault;
 public MovingSeasonRig(SeasonRollerRig.Config c,Params p,boolean worldBeamFault){this(c,p,worldBeamFault,false);}
 public MovingSeasonRig(SeasonRollerRig.Config c,Params p,boolean worldBeamFault,boolean diagnosticContinueDriving){this.c=c;this.p=p;this.worldBeamFault=worldBeamFault;contact=new MovingContact(p.mass,c.mass(),p.driveJ,c.inertia(),p.radius,c.radius());controller=new MovingPrototypeController(c.radius(),c.type().equals("NOTE")?2:1,diagnosticContinueDriving);sensors=new EncoderSim[]{EncoderSim.createForChannel(0),EncoderSim.createForChannel(2),EncoderSim.createForChannel(4),EncoderSim.createForChannel(6)};motors=new PWMSim[]{new PWMSim(0),new PWMSim(1),new PWMSim(3),new PWMSim(4)};beam=new DIOSim(8);unusedAux=new PWMSim(2);new AnalogGyroSim(0).setAngle(0);dm=DCMotor.getNEO(2);mm=DCMotor.getNEO(c.motors());q=new double[]{p.initialVelocity,p.initialVelocity,p.initialVelocity/p.radius,p.initialVelocity/p.radius,0,0};px=c.start();initialEnergy=contact.kinetic(q);inject();}
 private void inject(){for(int i=0;i<4;i++){sensors[i].setCount((int)Math.round(angles[i]/(2*Math.PI/2048)));if(i<2)sensors[i].setPeriod(q[i+2]==0?Double.MAX_VALUE:(2*Math.PI/2048)/q[i+2]);}beam.setValue(!SeasonRollerRig.occupied(c,worldBeamFault?px:px-bx));}
 public Sample step(boolean enabled,boolean mechanismEnabled,int n){if(n<20||n>200||200%n!=0)throw new IllegalArgumentException("Moving substeps");double dt=.02/n;if(dt*p.gear*p.gear*dm.KtNMPerAmp/(dm.rOhms*dm.KvRadPerSecPerVolt*p.driveJ)>.25||dt*c.gear()*c.gear()*mm.KtNMPerAmp/(mm.rOhms*mm.KvRadPerSecPerVolt*c.inertia())>.25)throw new IllegalArgumentException("Rotor stiffness");RoboRioSim.setVInVoltage(bus);controller.periodic(enabled,mechanismEnabled,p.target);
  for(int k=0;k<n;k++){if(unusedAux.getSpeed()!=0)throw new IllegalStateException("Unmodeled auxiliary demand");double[] duties=new double[4],emf=new double[4],r={dm.rOhms,dm.rOhms,mm.rOhms,mm.rOhms};for(int i=0;i<4;i++){duties[i]=motors[i].getSpeed();emf[i]=q[i+2]*(i<2?p.gear:c.gear())/(i<2?dm.KvRadPerSecPerVolt:mm.KvRadPerSecPerVolt);}if(Math.abs(duties[0]-duties[1])>1e-8)throw new IllegalArgumentException("Straight drive only");SharedSupply.Result supply;try{supply=SharedSupply.solve(12,.02,duties,emf,r);}catch(IllegalArgumentException error){throw new IllegalArgumentException("Moving season "+c.season()+" time="+elapsed+" relativeX="+(px-bx)+" duties="+java.util.Arrays.toString(duties)+" emf="+java.util.Arrays.toString(emf),error);}elapsed+=dt;bus=supply.volts();amps=supply.batteryAmps();driveA=duties[0]*supply.armatureAmps()[0]+duties[1]*supply.armatureAmps()[1];mechanismA=duties[2]*supply.armatureAmps()[2]+duties[3]*supply.armatureAmps()[3];double[] free=q.clone();for(int i=0;i<4;i++){double torque=(i<2?p.gear:c.gear())*(i<2?dm.KtNMPerAmp:mm.KtNMPerAmp)*supply.armatureAmps()[i];free[i+2]+=torque*dt/(i<2?p.driveJ:c.inertia());totalWork+=torque*dt*(q[i+2]+free[i+2])/2;}
   if(Math.abs(px-bx)>=c.window())released=true;engaged=!released;double dc=p.mu*p.mass*9.80665*.5*dt,mc=engaged?c.mu()*c.normal()*dt:0;var resolved=contact.resolve(free,new double[]{dc,dc,mc,mc});q=resolved.velocity();loss+=resolved.lossJ();reaction=resolved.impulse()[2]+resolved.impulse()[3];if(!engaged&&reaction!=0)throw new IllegalStateException("Released contact impulse");bx+=q[0]*dt;px+=q[1]*dt;for(int i=0;i<4;i++)angles[i]+=q[i+2]*dt;if(!Double.isFinite(bx)||!Double.isFinite(px)||Math.abs(bx)>20||Math.abs(px)>20)throw new IllegalStateException("Moving position domain");}
  inject();return new Sample(bx,px,px-bx,q[0],q[1],bus,amps,driveA,mechanismA,reaction,contact.kinetic(q)+loss-initialEnergy-totalWork,contact.momentum(q),engaged,released,SeasonRollerRig.occupied(c,px-bx),controller.done(),controller.faulted(),java.util.Arrays.copyOfRange(q,2,6));
 }
 @Override public void close(){controller.close();}
}
